def solution(nums):
    N = len(nums)
    count = 0
    for i in range(N):
        for j in range(N):
            for k in range(N):
                if nums[i] * nums[j] == nums[k]:
                    count += 1
    return count

def main():
    n = int(input())
    print(solution([int(input()) for _ in range(n)]))

if __name__ == "__main__":
    main()
